+ResolvedWeatherDesc resolveAPIWeatherDesc(const QString &desc)
+{
+    const auto key = desc.toUtf8();
+    const auto begin = std::begin(WEATHER_API_DESC_MAP);
+    const auto end = std::end(WEATHER_API_DESC_MAP);
+    const auto it = std::lower_bound(begin, end, key, [](const WeatherApiEntry &entry, const QByteArray &name) {
+        return std::strcmp(entry.key, name.constData()) < 0;
+    });
+    if (it != end && std::strcmp(it->key, key.constData()) == 0) {
+        return ResolvedWeatherDesc(QLatin1String(it->icon), it->desc.toString());
+    }
+    return {};
+}
+
+// Weather icon priority ranking (for choosing the most representative daily icon).
+// Sorted alphabetically by icon name (std::lower_bound (binary search) requires a sorted range to work correctly)
+struct IconRankEntry {
+    const char *iconName;
+    int rank;
+};
+
+static constexpr const IconRankEntry WEATHER_ICON_PRIORITY_RANK[] = {
+    {"weather-clear", 0},
+    {"weather-clouds", 2},
+    {"weather-few-clouds", 1},
+    {"weather-fog", 3},
+    {"weather-freezing-rain", 6},
+    {"weather-freezing-scattered-rain", 6},
+    {"weather-freezing-scattered-rain-storm", 7},
+    {"weather-freezing-storm", 6},
+    {"weather-hail", 5},
+    {"weather-mist", 3},
+    {"weather-none-available", -1},
+    {"weather-showers", 5},
+    {"weather-showers-scattered", 4},
+    {"weather-showers-scattered-storm", 7},
+    {"weather-snow", 5},
+    {"weather-snow-rain", 6},
+    {"weather-snow-scattered", 4},
+    {"weather-snow-scattered-storm", 7},
+    {"weather-snow-storm", 7},
+    {"weather-storm", 7},
+};
+
+int weatherIconPriorityRank(const QString &icon)
+{
+    // Strip day/night suffix to match base icon names in the priority table.
+    QString baseIcon = icon;
+    if (baseIcon.endsWith(QLatin1String("-day"))) {
+        baseIcon.chop(4);
+    } else if (baseIcon.endsWith(QLatin1String("-night"))) {
+        baseIcon.chop(6);
+    }
+
+    const auto begin = std::begin(WEATHER_ICON_PRIORITY_RANK);
+    const auto end = std::end(WEATHER_ICON_PRIORITY_RANK);
+    const auto it = std::lower_bound(begin, end, baseIcon, [](const IconRankEntry &entry, const QString &name) {
+        return QLatin1String(entry.iconName) < name;
+    });
+    if (it != end && QLatin1String(it->iconName) == baseIcon) {
+        return it->rank;
+    }
+    return 0;
+}
