+// Hourly forecast data simplified inline version of KWeatherCore::HourlyWeatherForecast
+
+struct HourlyForecast {
+    QDateTime date;
+    QString weatherDescription;
+    QString weatherIcon;
+    QString symbolCode;
+    double temperature = 0;
+    double pressure = 0;
+    double windDirection = NAN;
+    double windSpeed = 0;
+    double humidity = 0;
+    double fog = 0;
+    double uvIndex = 0;
+    double precipitationAmount = 0;
+    double precipitationProbability = NAN;
+    double dewPointTemperature = 0;
+    double windGust = NAN;
+    bool isDay = true;
+};
+
+// Daily forecast aggregation simplified inline version of KWeatherCore::DailyWeatherForecast
+
+struct DailyForecast {
+    QDate date;
+    double maxTemp = std::numeric_limits<double>::lowest();
+    double minTemp = std::numeric_limits<double>::max();
+    double precipitation = 0;
+    double uvIndex = 0;
+    double humidity = 0;
+    double pressure = 0;
+    QString weatherIcon = QStringLiteral("weather-none-available");
+    QString weatherDescription = QStringLiteral("Unknown");
+    std::vector<HourlyForecast> hourly;
+
+    void addHourly(HourlyForecast &&h)
+    {
+        if (!date.isValid()) {
+            date = h.date.date();
+            weatherDescription = h.weatherDescription;
+            weatherIcon = h.weatherIcon;
+        }
+
+        if (date.daysTo(h.date.date()) == 0) {
+            if (weatherIconPriorityRank(h.weatherIcon) >= weatherIconPriorityRank(weatherIcon)) {
+                weatherDescription = h.weatherDescription;
+                weatherIcon = h.weatherIcon;
+            }
+            precipitation += h.precipitationAmount;
+            uvIndex = std::max(uvIndex, h.uvIndex);
+            humidity = std::max(humidity, h.humidity);
+            pressure = std::max(pressure, h.pressure);
+            maxTemp = std::max(maxTemp, h.temperature);
+            minTemp = std::min(minTemp, h.temperature);
+        }
+
+        hourly.push_back(std::move(h));
+    }
+};
