+static void parseOneElement(const QJsonObject &obj, std::vector<HourlyForecast> &out)
+{
+    const QJsonObject data = obj[QLatin1String("data")].toObject();
+    const QJsonObject instant = data[QLatin1String("instant")].toObject()[QLatin1String("details")].toObject();
+
+    if (!data.contains(QLatin1String("next_6_hours")) && !data.contains(QLatin1String("next_1_hours"))) {
+        return;
+    }
+
+    QString symbolCode;
+    double precipitationAmount = 0;
+    double precipitationProbability = NAN;
+
+    if (data.contains(QLatin1String("next_1_hours"))) {
+        const QJsonObject next = data[QLatin1String("next_1_hours")].toObject();
+        symbolCode = next[QLatin1String("summary")].toObject()[QLatin1String("symbol_code")].toString(QLatin1String("unknown"));
+        precipitationAmount = next[QLatin1String("details")].toObject()[QLatin1String("precipitation_amount")].toDouble();
+        const QJsonObject details = next[QLatin1String("details")].toObject();
+        if (details.contains(QLatin1String("probability_of_precipitation"))) {
+            precipitationProbability = details[QLatin1String("probability_of_precipitation")].toDouble();
+        }
+    } else {
+        const QJsonObject next = data[QLatin1String("next_6_hours")].toObject();
+        symbolCode = next[QLatin1String("summary")].toObject()[QLatin1String("symbol_code")].toString(QLatin1String("unknown"));
+        precipitationAmount = next[QLatin1String("details")].toObject()[QLatin1String("precipitation_amount")].toDouble();
+        const QJsonObject details = next[QLatin1String("details")].toObject();
+        if (details.contains(QLatin1String("probability_of_precipitation"))) {
+            precipitationProbability = details[QLatin1String("probability_of_precipitation")].toDouble();
+        }
+    }
+
+    symbolCode = symbolCode.split(QLatin1Char('_'))[0];
+
+    HourlyForecast h;
+    h.date = QDateTime::fromString(obj.value(QLatin1String("time")).toString(), Qt::ISODate);
+    h.temperature = instant[QLatin1String("air_temperature")].toDouble();
+    h.pressure = instant[QLatin1String("air_pressure_at_sea_level")].toDouble();
+    h.windDirection = instant[QLatin1String("wind_from_direction")].toDouble();
+    h.windSpeed = instant[QLatin1String("wind_speed")].toDouble();
+    h.humidity = instant[QLatin1String("relative_humidity")].toDouble();
+    h.fog = instant[QLatin1String("fog_area_fraction")].toDouble();
+    h.uvIndex = instant[QLatin1String("ultraviolet_index_clear_sky")].toDouble();
+    h.precipitationAmount = precipitationAmount;
+    h.precipitationProbability = precipitationProbability;
+    h.dewPointTemperature = instant[QLatin1String("dew_point_temperature")].toDouble();
+    if (instant.contains(QLatin1String("wind_speed_of_gust"))) {
+        h.windGust = instant[QLatin1String("wind_speed_of_gust")].toDouble();
+    }
+    h.symbolCode = symbolCode;
+    out.push_back(std::move(h));
+}
+
+static void parseLocationForecast(const QByteArray &data, std::vector<HourlyForecast> &out)
+{
+    const QJsonDocument doc = QJsonDocument::fromJson(data);
+    if (!doc.isObject()) {
+        return;
+    }
+    const QJsonObject prop = doc.object()[QLatin1String("properties")].toObject();
+    if (!prop.contains(QLatin1String("timeseries"))) {
+        return;
+    }
+    const QJsonArray timeseries = prop[QLatin1String("timeseries")].toArray();
+    for (const auto &ref : std::as_const(timeseries)) {
+        parseOneElement(ref.toObject(), out);
+    }
+}
+
+static void applySunriseAndAggregate(std::vector<HourlyForecast> &hourly,
+                                     double latitude,
+                                     double longitude,
+                                     const QTimeZone &tz,
+                                     std::vector<DailyForecast> &days,
+                                     bool (*isNightTimeFn)(const QDateTime &, double, double))
+{
+    for (auto &h : hourly) {
+        h.date = h.date.toTimeZone(tz);
+        bool isDay = !isNightTimeFn(h.date, latitude, longitude);
+        h.isDay = isDay;
+        const QString suffix = isDay ? QStringLiteral("_day") : QStringLiteral("_night");
+        const auto resolved = resolveAPIWeatherDesc(h.symbolCode + suffix);
+        h.weatherIcon = resolved.icon;
+        h.weatherDescription = resolved.desc;
+
+        // Aggregate into daily
+        bool found = false;
+        for (int i = static_cast<int>(days.size()) - 1; i >= 0; --i) {
+            if (days[i].date == h.date.date()) {
+                days[i].addHourly(std::move(h));
+                found = true;
+                break;
+            }
+        }
+        if (!found) {
+            DailyForecast day;
+            day.addHourly(std::move(h));
+            days.push_back(std::move(day));
+        }
+    }
+}
