+static QString windDirectionFromDegree(double deg)
+{
+    if (deg < 0) {
+        return {};
+    }
+    static const QStringList dirs = {
+        u"N"_s,
+        u"NNE"_s,
+        u"NE"_s,
+        u"ENE"_s,
+        u"E"_s,
+        u"ESE"_s,
+        u"SE"_s,
+        u"SSE"_s,
+        u"S"_s,
+        u"SSW"_s,
+        u"SW"_s,
+        u"WSW"_s,
+        u"W"_s,
+        u"WNW"_s,
+        u"NW"_s,
+        u"NNW"_s,
+    };
+    int idx = qRound(deg / 22.5) % 16;
+    return dirs[idx];
+}
