+KJob *MetNoIon::requestAPIJob(const QUrl &url, QByteArray &result)
+{
+    KIO::TransferJob *getJob = KIO::get(url, KIO::Reload, KIO::HideProgressInfo);
+    // It is preferrably to add a descriptive User-Agent identifying the application
+    // - api.met.no require this in their 'Terms of Service':
+    //   https://api.met.no/doc/TermsOfService#:~:text=Identification
+    // - Photon (Komoot) doesn't seem to explicitly require a User-Agent, but we should
+    //   still identify ourselves as good citizens of the internet:
+    //   https://photon.komoot.io/
+    static const QString userAgent =
+        QStringLiteral("KDEPlasmaAddons/%1 invent.kde.org/plasma/kdeplasma-addons").arg(QStringLiteral(KDEPLASMA_ADDONS_VERSION_STRING));
+    getJob->addMetaData(u"UserAgent"_s, userAgent);
+    getJob->addMetaData(u"cookies"_s, u"none"_s);
+
+    qCDebug(WEATHER::ION::METNO) << "Requesting URL:" << url;
+    qCDebug(WEATHER::ION::METNO) << "Outgoing metadata:" << getJob->outgoingMetaData();
+
+    connect(getJob, &KIO::TransferJob::data, this, [&result](KIO::Job *job, const QByteArray &data) {
+        Q_UNUSED(job);
+        if (data.isEmpty()) {
+            return;
+        }
+        result.append(data);
+    });
+
+    return getJob;
+}
