+void MetNoIon::findPlaces(std::shared_ptr<QPromise<std::shared_ptr<Locations>>> promise, const QString &searchString)
+{
+    m_locationPromise = promise;
+    m_locationPromise->start();
+    m_locationsData.clear();
+
+    QUrl url(QStringLiteral("https://photon.komoot.io/api"));
+    QUrlQuery urlQuery;
+    urlQuery.addQueryItem(QStringLiteral("q"), searchString);
+    urlQuery.addQueryItem(QStringLiteral("limit"), QStringLiteral("30"));
+
+    // Ask Photon to return localized names where possible. The public Photon
+    // instance only accepts a fixed set of two-letter language codes (the API
+    // replies with HTTP 400 listing them when given an unknown one)
+    // FIXME At this time there doesn't seem to be a discovery endpoint for
+    // the supported languages so we don't have a choice but to use a whitelist
+    // approach. If the API changes, we should fetch the languages
+    // automatically. The other approach of sending an invalid request to get the
+    // list in the reply is really brittle and we shouldn't rely on it.
+    // Bug tracking this issue: https://github.com/komoot/photon/issues/1074
+    static const QSet<QString> photonSupportedLanguages{
+        u"de"_s,
+        u"en"_s,
+        u"fr"_s,
+    };
+    const QString primaryLanguage = QLocale().bcp47Name().section(QLatin1Char('-'), 0, 0);
+    if (photonSupportedLanguages.contains(primaryLanguage)) {
+        urlQuery.addQueryItem(QStringLiteral("lang"), primaryLanguage);
+    }
+    url.setQuery(urlQuery);
+
+    const auto getJob = requestAPIJob(url, m_locationsData);
+    connect(getJob, &KJob::result, this, [this](KJob *job) {
+        auto locations = std::make_shared<Locations>();
+
+        if (job->error()) {
+            qCWarning(WEATHER::ION::METNO) << "Location query error:" << job->errorString();
+            locations->setError();
+        } else {
+            const QJsonArray features = QJsonDocument::fromJson(m_locationsData).object().value(QLatin1String("features")).toArray();
+            if (features.isEmpty()) {
+                qCWarning(WEATHER::ION::METNO) << "No locations found";
+                locations->setError();
+            } else {
+                qCDebug(WEATHER::ION::METNO) << "Photon returned" << features.size() << "result(s)";
+                for (const auto &featRef : std::as_const(features)) {
+                    const auto feature = featRef.toObject();
+                    const auto props = feature.value(QLatin1String("properties")).toObject();
+                    const auto coordinates = feature.value(QLatin1String("geometry")).toObject().value(QLatin1String("coordinates")).toArray();
+
+                    // Filter only the cities and villages (towns/hamlets)
+                    static const QSet<QString> allowedAddressTypes{
+                        u"city"_s,
+                        u"town"_s,
+                        u"village"_s,
+                        u"hamlet"_s,
+                    };
+                    const QString addressType = props.value(QLatin1String("osm_value")).toString();
+                    if (!allowedAddressTypes.contains(addressType)) {
+                        continue;
+                    }
+                    if (coordinates.size() < 2) {
+                        continue;
+                    }
+
+                    const double lon = coordinates.at(0).toDouble();
+                    const double lat = coordinates.at(1).toDouble();
+                    QString name = props.value(QLatin1String("name")).toString();
+                    const QString country = props.value(QLatin1String("country")).toString();
+                    const QString county = props.value(QLatin1String("county")).toString();
+
+                    // For villages and hamlets, show the enclosing town (or city) in
+                    // parentheses when it is a different place. Cities/towns don't
+                    // need this since they are already the top settlement level
+                    QString parentSettlement;
+                    if (addressType == QLatin1String("village") || addressType == QLatin1String("hamlet")) {
+                        const QString candidate = props.value(QLatin1String("city")).toString();
+                        if (!candidate.isEmpty() && candidate != name) {
+                            parentSettlement = candidate;
+                        }
+                    }
+
+                    // Build "Name (Parent), County, Country" omitting empty parts
+                    QStringList displayParts;
+                    if (parentSettlement.isEmpty()) {
+                        displayParts << name;
+                    } else {
+                        displayParts << QStringLiteral("%1 (%2)").arg(name, parentSettlement);
+                    }
+                    if (!county.isEmpty()) {
+                        displayParts << county;
+                    }
+                    if (!country.isEmpty()) {
+                        displayParts << country;
+                    }
+                    const QString displayName = displayParts.join(QStringLiteral(", "));
+
+                    Location loc;
+                    loc.setDisplayName(displayName);
+                    loc.setStation(name);
+                    loc.setCoordinates(QPointF(lon, lat));
+                    loc.setPlaceInfo(QStringLiteral("%1|%2|%3|%4").arg(name, QString::number(lat, 'f', 4), QString::number(lon, 'f', 4), country));
+                    locations->addLocation(loc);
+                }
+            }
+        }
+
+        m_locationPromise->addResult(locations);
+        m_locationPromise->finish();
+        m_locationPromise.reset();
+    });
+}
