+void MetNoIon::fetchForecast(std::shared_ptr<QPromise<std::shared_ptr<Forecast>>> promise, const QString &placeInfo)
+{
+    m_forecastPromise = promise;
+    m_forecastPromise->start();
+
+    const QStringList parts = placeInfo.split('|'_L1);
+    if (parts.size() < 4) {
+        qCWarning(WEATHER::ION::METNO) << "Invalid placeInfo:" << placeInfo;
+        m_forecastPromise->finish();
+        m_forecastPromise.reset();
+        return;
+    }
+
+    const QString name = parts[0];
+    const double lat = parts[1].toDouble();
+    const double lon = parts[2].toDouble();
+    const QString country = parts[3];
+
+    // Determine timezone from coordinates
+    const QString timezone = QString::fromUtf8(KTimeZone::fromLocation(lat, lon));
+
+    // Request forecast from api.met.no
+    QUrl url(QStringLiteral("https://api.met.no/weatherapi/locationforecast/2.0/complete"));
+    QUrlQuery query;
+    query.addQueryItem(QStringLiteral("lat"), toFixedString(lat));
+    query.addQueryItem(QStringLiteral("lon"), toFixedString(lon));
+    url.setQuery(query);
+
+    m_forecastData.clear();
+
+    const auto getJob = requestAPIJob(url, m_forecastData);
+    connect(getJob, &KJob::result, this, [this, name, country, lat, lon, timezone](KJob *job) {
+        auto forecast = std::make_shared<Forecast>();
+
+        if (job->error()) {
+            qCWarning(WEATHER::ION::METNO) << "Forecast error:" << job->errorString();
+            forecast->setError();
+            m_forecastPromise->addResult(forecast);
+            m_forecastPromise->finish();
+            m_forecastPromise.reset();
+            return;
+        }
+
+        // Parse the MET Norway JSON response
+        std::vector<HourlyForecast> hourly;
+        parseLocationForecast(m_forecastData, hourly);
+
+        // Apply sunrise/sunset and aggregate into daily forecasts
+        QTimeZone tz(timezone.toUtf8());
+        if (!tz.isValid()) {
+            tz = QTimeZone::utc();
+        }
+        std::vector<DailyForecast> days;
+        applySunriseAndAggregate(hourly, lat, lon, tz, days, &Ion::isNightTime);
+
+        // Build the Forecast result
+        Station station;
+        station.setPlace(name);
+        station.setStation(name);
+        station.setCountry(country);
+        station.setCoordinates(lat, lon);
+        forecast->setStation(station);
+
+        MetaData metaData;
+        metaData.setCredit(i18nc("credit line", "Source: Norwegian Meteorological Institute"));
+        metaData.setCreditURL(u"https://www.met.no/"_s);
+        metaData.setTemperatureUnit(KUnitConversion::Celsius);
+        metaData.setWindSpeedUnit(KUnitConversion::KilometerPerHour);
+        metaData.setPressureUnit(KUnitConversion::Hectopascal);
+        metaData.setHumidityUnit(KUnitConversion::Percent);
+        metaData.setPrecipUnit(KUnitConversion::Millimeter);
+        forecast->setMetadata(metaData);
+
+        // Current observation from the first hourly entry
+        if (!days.empty() && !days.front().hourly.empty()) {
+            const auto &h = days.front().hourly.front();
+
+            LastObservation obs;
+            obs.setObservationTimestamp(h.date);
+            obs.setTemperature(h.temperature);
+            obs.setHumidity(h.humidity);
+            obs.setPressure(h.pressure);
+            obs.setWindSpeed(h.windSpeed);
+            obs.setConditionIcon(getWeatherIcon(conditionFromIconName(h.weatherIcon)));
+            obs.setCurrentConditions(h.weatherDescription);
+            obs.setDewpoint(h.dewPointTemperature);
+
+            if (h.uvIndex > 0) {
+                obs.setUVIndex(static_cast<int>(std::round(h.uvIndex)));
+            }
+            if (!std::isnan(h.windGust)) {
+                obs.setWindGust(h.windGust);
+            }
+            if (h.windDirection >= 0) {
+                obs.setWindDirection(windDirectionFromDegree(h.windDirection));
+            }
+
+            forecast->setLastObservation(obs);
+        }
+
+        // Future days forecast
+        if (!days.empty()) {
+            auto futureDays = std::make_shared<FutureDays>();
+            int dayNum = 0;
+
+            for (const auto &day : days) {
+                FutureDayForecast futureDay(day.date.startOfDay(day.hourly.front().date.timeZone()));
+
+                // Split hourly entries into daytime and nighttime
+                std::vector<const HourlyForecast *> dayHours;
+                std::vector<const HourlyForecast *> nightHours;
+                for (const auto &h : day.hourly) {
+                    if (h.isDay) {
+                        dayHours.push_back(&h);
+                    } else {
+                        nightHours.push_back(&h);
+                    }
+                }
+
+                // Helper to build a FutureForecast from a set of hourly entries
+                auto buildForecast = [this](const std::vector<const HourlyForecast *> &hours) -> std::optional<FutureForecast> {
+                    if (hours.empty()) {
+                        return std::nullopt;
+                    }
+                    double maxT = std::numeric_limits<double>::lowest();
+                    double minT = std::numeric_limits<double>::max();
+                    double maxPrecipProb = qQNaN();
+                    QString bestIcon = hours.front()->weatherIcon;
+                    QString bestDesc = hours.front()->weatherDescription;
+
+                    for (const auto *h : hours) {
+                        maxT = std::max(maxT, h->temperature);
+                        minT = std::min(minT, h->temperature);
+                        if (weatherIconPriorityRank(h->weatherIcon) >= weatherIconPriorityRank(bestIcon)) {
+                            bestIcon = h->weatherIcon;
+                            bestDesc = h->weatherDescription;
+                        }
+                        if (!qIsNaN(h->precipitationProbability)) {
+                            maxPrecipProb = qIsNaN(maxPrecipProb) ? h->precipitationProbability : std::max(maxPrecipProb, h->precipitationProbability);
+                        }
+                    }
+
+                    FutureForecast f;
+                    f.setHighTemp(maxT);
+                    f.setLowTemp(minT);
+                    f.setConditionIcon(getWeatherIcon(conditionFromIconName(bestIcon)));
+                    f.setCondition(bestDesc);
+                    if (!qIsNaN(maxPrecipProb)) {
+                        f.setConditionProbability(maxPrecipProb);
+                    }
+                    return f;
+                };
+
+                if (auto dayForecast = buildForecast(dayHours)) {
+                    futureDay.setDaytime(*dayForecast);
+                }
+                if (auto nightForecast = buildForecast(nightHours)) {
+                    futureDay.setNight(*nightForecast);
+                }
+
+                futureDays->addDay(futureDay);
+
+                if (++dayNum >= 7) {
+                    break;
+                }
+            }
+
+            forecast->setFutureDays(futureDays);
+        }
+
+        m_forecastPromise->addResult(forecast);
+        m_forecastPromise->finish();
+        m_forecastPromise.reset();
+    });
+}
